async function initializeCloud(){
 if(!window.MyCalendarCloud){cloudReady=true;renderAccount();return}
 try{
  const result=await window.MyCalendarCloud.init(async remote=>{
   state={...defaults,...remote};
   currentDate=parseDate(state.current||defaults.current);
   localStorage.setItem(STORE,JSON.stringify(state));
   render();
  });
  cloudReady=!!result.configured;renderAccount(result.user||null);
  if(result.providerToken){googleAccessToken=result.providerToken;googleTokenExpiresAt=Date.now()+50*60*1000;state.googleSetupComplete=true;renderGoogleStatus()}
  if(result.signedIn&&!result.hadRemote){window.MyCalendarCloud.queueSave(structuredClone(state));toast('이 기기의 캘린더를 클라우드에 저장했습니다')}
  else if(result.signedIn&&result.hadRemote)toast('클라우드 캘린더를 불러왔습니다');
  if(result.signedIn&&result.providerToken)setTimeout(automaticGoogleSync,300);
 }catch(error){cloudReady=true;renderAccount();console.error('My Calendar cloud initialization failed:',error);toast('클라우드 연결에 실패했습니다')}
}
window.addEventListener('my-calendar-auth-changed',event=>{const token=event.detail?.providerToken||'';googleAccessToken=token;googleTokenExpiresAt=token?Date.now()+50*60*1000:0;state.googleSetupComplete=!!event.detail?.signedIn;cloudReady=true;renderAccount(event.detail?.user||null);renderGoogleStatus();if(token)setTimeout(automaticGoogleSync,500)});
